// Abandon universal ontology; enforce point-in-time semantic contracts at the boundary
def resolve_agent_context(agent_intent, caller_identity):
    # 1. Resolve to a single versioned metric contract, failing closed on ambiguity
    metric_contract = semantic_registry.lookup(agent_intent.term, caller_identity.domain)
    if metric_contract.is_ambiguous: raise UnresolvableContextError(agent_intent.term)

    # 2. Derive least-privilege row/field filters from caller identity, not the agent's role
    security_predicate = authz_engine.derive_predicates(caller_identity, metric_contract.required_clearance)

    # 3. Compile contract into native platform dialect with embedded security predicates
    executable_target = metric_contract.compile_for(agent_intent.target_tool, security_predicate)

    # 4. Return signed execution plan rather than raw context to prevent downstream drift
    return emit_verifiable_intent(executable_target, semantic_hash=metric_contract.version_hash)

